namespace TradeWebAPI.Entities
{
    // A user waiting for support. The row exists only while waiting:
    // closing the support (by the user or anyone else) deletes it.
    public class SupportRequest
    {
        public int Id { get; set; }

        // Shared with the BFF/frontend as the socket room name. Generated by the server.
        public Guid ConversationId { get; set; } = Guid.NewGuid();

        public int UserId { get; set; }
        public User User { get; set; } = null!;

        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    }
}
